def _set_edital_categoria(apps, schema_editor):
    """
    Para cada Edital existente: se qualquer cargo associado possuir o código
    começando com '707', marca como 'docente', senão marca como 'tae'.
    """
    Edital = apps.get_model('remanejamento', 'Edital')

    for edital in Edital.objects.all():
        eh_edital_docente = False
        # iterate cargos
        for cargo in edital.cargos.all():
            codigo = (getattr(cargo, 'codigo', '') or '')
            # normaliza e verifica prefixo 707 - tabela cargos docente e código 702001 - MGBTT
            codigo_str = (str(codigo) or '').strip()
            if codigo_str.startswith('707') or codigo_str == '702001':
                eh_edital_docente = True
                break
        edital.categoria = 'docente' if eh_edital_docente else 'tae'
        edital.save(update_fields=['categoria'])


def _unset_edital_categoria(apps, schema_editor):
    """Reverte definindo categoria para NULL (limpa o valor)."""
    Edital = apps.get_model('remanejamento', 'Edital')
    Edital.objects.update(categoria=None)


